(function() {
  'use strict';

  const api = window.CardSpoke.utils;

  CardSpoke_MODS.register('smart-links-mod', {
    meta: {
      name: 'Smart Links Mod',
      type: 'Mod',
      version: '1.0.0',
      creator: 'CardSpoke',
      description: 'Enhanced linking with bidirectional references, link suggestions, and visualization'
    },

    linkRegex: /\[\[([^\]]+)\]\]/g, // [[Card Title]] syntax
    urlRegex: /(https?:\/\/[^\s]+)/g,
    linkCache: new Map(),

    onAppInit(ctx) {
      ctx.logger.log('Smart Links Mod initialized');
      this.buildLinkCache(ctx);
      this.addLinkPanel(ctx);
    },

    async buildLinkCache(ctx) {
      // Build a cache of all card links
      this.linkCache.clear();

      const allCards = Object.values(window.store?.cards || {});

      for (const card of allCards) {
        const links = this.extractLinks(card.body);
        if (links.length > 0) {
          this.linkCache.set(card.id, links);
        }
      }

      ctx.logger.log('Link cache built:', this.linkCache.size, 'cards with links');
    },

    extractLinks(text) {
      const links = [];
      let match;

      // Extract [[wiki-style]] links
      const wikiRegex = new RegExp(this.linkRegex);
      while ((match = wikiRegex.exec(text)) !== null) {
        links.push({
          type: 'wiki',
          text: match[1],
          raw: match[0]
        });
      }

      // Extract URLs
      const urlRegex = new RegExp(this.urlRegex);
      while ((match = urlRegex.exec(text)) !== null) {
        links.push({
          type: 'url',
          text: match[1],
          raw: match[0]
        });
      }

      return links;
    },

    async onCardRender(ctx, card, element) {
      // Convert [[links]] to clickable elements
      const bodyElement = element.querySelector('.card-body, .card-text, p');
      if (!bodyElement) return;

      let html = bodyElement.innerHTML;

      // Replace [[Card Title]] with clickable links
      html = html.replace(this.linkRegex, (match, title) => {
        const linkedCard = this.findCardByTitle(title);
        if (linkedCard) {
          return `<a href="#" class="wiki-link" data-card-id="${linkedCard.id}" title="Go to: ${title}">[[${title}]]</a>`;
        } else {
          return `<span class="wiki-link-missing" title="Card not found">[[${title}]]</span>`;
        }
      });

      // Enhance URLs with icons
      html = html.replace(this.urlRegex, (match) => {
        return `<a href="${match}" class="external-link" target="_blank" rel="noopener noreferrer">🔗 ${match}</a>`;
      });

      bodyElement.innerHTML = html;

      // Add click handlers for wiki links
      const wikiLinks = bodyElement.querySelectorAll('.wiki-link');
      wikiLinks.forEach(link => {
        link.addEventListener('click', (e) => {
          e.preventDefault();
          const cardId = link.dataset.cardId;
          this.navigateToCard(ctx, cardId);
        });
      });

      // Add backlinks section
      this.addBacklinks(ctx, card, element);
    },

    findCardByTitle(title) {
      const allCards = Object.values(window.store?.cards || {});
      return allCards.find(card => 
        card.title.toLowerCase() === title.toLowerCase()
      );
    },

    navigateToCard(ctx, cardId) {
      // Navigate to the linked card
      if (window.loadCard) {
        window.loadCard(cardId);
      } else {
        // Fallback: update URL
        const url = new URL(window.location);
        url.searchParams.set('card', cardId);
        window.history.pushState({}, '', url);
        window.location.reload();
      }
    },

    addBacklinks(ctx, card, element) {
      const backlinks = this.getBacklinks(card);

      if (backlinks.length === 0) return;

      const backlinksSection = document.createElement('div');
      backlinksSection.className = 'smart-links-backlinks';
      backlinksSection.innerHTML = `
        <div class="backlinks-header">⬅️ Linked by ${backlinks.length} card${backlinks.length !== 1 ? 's' : ''}:</div>
        <div class="backlinks-list">
          ${backlinks.map(bl => `
            <div class="backlink-item" data-card-id="${bl.id}">
              <span class="backlink-title">${bl.title}</span>
            </div>
          `).join('')}
        </div>
      `;

      element.appendChild(backlinksSection);

      // Add click handlers
      const backlinksItems = backlinksSection.querySelectorAll('.backlink-item');
      backlinksItems.forEach(item => {
        item.addEventListener('click', () => {
          const cardId = item.dataset.cardId;
          this.navigateToCard(ctx, cardId);
        });
      });
    },

    getBacklinks(card) {
      const backlinks = [];
      const allCards = Object.values(window.store?.cards || {});

      for (const otherCard of allCards) {
        if (otherCard.id === card.id) continue;

        const links = this.extractLinks(otherCard.body);
        const hasLink = links.some(link => 
          link.type === 'wiki' && 
          link.text.toLowerCase() === card.title.toLowerCase()
        );

        if (hasLink) {
          backlinks.push({
            id: otherCard.id,
            title: otherCard.title
          });
        }
      }

      return backlinks;
    },

    addLinkPanel(ctx) {
      // Add a floating panel for link suggestions
      this.panel = document.createElement('div');
      this.panel.id = 'smart-links-panel';
      this.panel.innerHTML = `
        <div class="smart-links-panel-header">
          <span>🔗 Link Suggestions</span>
          <button class="smart-links-close">×</button>
        </div>
        <div class="smart-links-panel-body">
          <div class="smart-links-instructions">
            Use [[Card Title]] to create links between cards.
            <br>Type [[ to see suggestions.
          </div>
          <div class="smart-links-stats">
            <div>Total Links: <span id="smart-links-total">0</span></div>
            <div>Orphan Cards: <span id="smart-links-orphans">0</span></div>
          </div>
        </div>
      `;

      document.body.appendChild(this.panel);

      const closeBtn = this.panel.querySelector('.smart-links-close');
      closeBtn.addEventListener('click', () => {
        this.panel.style.display = 'none';
      });

      // Update stats
      this.updatePanelStats(ctx);
    },

    updatePanelStats(ctx) {
      if (!this.panel) return;

      const totalLinks = Array.from(this.linkCache.values())
        .reduce((sum, links) => sum + links.length, 0);

      const allCards = Object.values(window.store?.cards || {});
      const orphans = allCards.filter(card => {
        const hasOutgoingLinks = this.linkCache.has(card.id);
        const hasIncomingLinks = this.getBacklinks(card).length > 0;
        return !hasOutgoingLinks && !hasIncomingLinks && !card.parentId;
      });

      const totalEl = this.panel.querySelector('#smart-links-total');
      const orphansEl = this.panel.querySelector('#smart-links-orphans');

      if (totalEl) totalEl.textContent = totalLinks;
      if (orphansEl) orphansEl.textContent = orphans.length;
    },

    async onCardSave(ctx, card, saveInfo) {
      // Update link cache when card is saved
      const links = this.extractLinks(card.body);
      if (links.length > 0) {
        this.linkCache.set(card.id, links);
      } else {
        this.linkCache.delete(card.id);
      }

      this.updatePanelStats(ctx);

      // Store link data in modsData
      if (!card.modsData) card.modsData = {};
      if (!card.modsData[ctx.modId]) card.modsData[ctx.modId] = {};

      card.modsData[ctx.modId].links = links;
      card.modsData[ctx.modId].linkCount = links.length;
      card.modsData[ctx.modId].backlinks = this.getBacklinks(card).map(bl => bl.id);

      await ctx.utils.updateCard(card.id, { modsData: card.modsData });
    },

    onCardDelete(ctx, cardId) {
      // Remove from cache when card is deleted
      this.linkCache.delete(cardId);
      this.updatePanelStats(ctx);
    },

    onDisable(ctx) {
      if (this.panel && this.panel.parentNode) {
        this.panel.parentNode.removeChild(this.panel);
      }
    }
  });
})();

